import{_ as t,a,b as o}from"./chunks/a17cddeda1e3aeab787b.DD_pJpP6.js";import{_ as s,C as n,o as i,c as l,j as e,a as h,E as m,a6 as c}from"./chunks/framework.CnPv4DE1.js";const T=JSON.parse('{"title":"一人企业路线图（99%的创作者都犯了这个错误）","description":"","frontmatter":{"title":"一人企业路线图（99%的创作者都犯了这个错误）","originalTitle":"The One-Person Business Roadmap (99% Of Creators Make This Mistake)","date":"2022-12-01","originalUrl":"https://thedankoe.com/letters/the-one-person-business-roadmap-99-of-creators-make-this-mistake/","minutes":18,"sourceHash":"829bb8776b98c33d927a6223c6fdd2ab7756590ca3501a93a0c601e223479130","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-one-person-business-roadmap-99-of-creators-make-this-mistake/"}]]},"headers":[],"relativePath":"letters/the-one-person-business-roadmap-99-of-creators-make-this-mistake.md","filePath":"letters/the-one-person-business-roadmap-99-of-creators-make-this-mistake.md"}'),u={name:"letters/the-one-person-business-roadmap-99-of-creators-make-this-mistake.md"};function g(d,p,f,k,b,_){const r=n("ArticleMeta");return i(),l("div",null,[p[0]||(p[0]=e("h1",{id:"一人企业路线图-99-的创作者都犯了这个错误",tabindex:"-1"},[h("一人企业路线图（99%的创作者都犯了这个错误） "),e("a",{class:"header-anchor",href:"#一人企业路线图-99-的创作者都犯了这个错误","aria-label":'Permalink to "一人企业路线图（99%的创作者都犯了这个错误）"'},"​")],-1)),m(r),p[1]||(p[1]=c('<p>在我们开始之前：这封信是一人企业系列中的其中一封。这里还有几篇。</p><p><a href="https://thedankoe.com/the-one-person-business-model-how-to-monetize-yourself/" target="_blank" rel="noreferrer">一人企业商业模式（如何将你自己产品化）</a></p><p><a href="https://thedankoe.com/the-rise-of-the-value-creator-a-new-career-path/" target="_blank" rel="noreferrer">价值创作者的崛起（多面手和自我提升者的职业道路）</a></p><p><a href="https://thedankoe.com/11-insights-i-wish-i-knew-to-grow-my-one-person-business/" target="_blank" rel="noreferrer">作为创作者我希望早点知道的11个洞察</a></p><p><a href="https://thedankoe.com/you-have-100000-of-knowledge-trapped-in-your-brain/" target="_blank" rel="noreferrer">你的大脑里有一个价值10万美元的产品</a></p><p>最后，所有这些都只是一些有趣的文章。是的，它们很有价值，但真正的价值在于我所完善的那些系统，正是它们维持着我这个每月进账10万美元上下的小小一人企业。</p><p>如果你想要一个包含这些系统的Notion仪表板来管理你的业务（以及关于品牌、内容、产品、营销和推广的全套教育），那么你可能会喜欢《数字经济学》（Digital Economics）。</p><p><a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">在此注册，为新经济将你自己产品化。</a></p><hr><p><a href="https://www.youtube.com/embed/M5IMu7c5f_E?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>如果你正在建立一个一人创作者企业，请注意了。</p><p>我在这个游戏里已经玩了3年了。</p><p>我见过大大小小的账号从地图上销声匿迹。</p><p>我见过小账号每月赚10万美元。</p><p>我见过大账号每月只赚1千美元。</p><p>大多数人看到这些，会认为其中某一种情况很糟糕。</p><p>认为他们要么应该坚持做高价服务却永远没有足够的时间，要么获得了大量粉丝却永远赚不到足够生存的钱。</p><p>独立创业（solopreneurship）的拼图中有一块至关重要的部分，却无人提及。</p><p>虽然大多数人认为你必须牺牲时间或金钱，但我在这里要告诉你，你可以两者兼得。</p><p>怎么做？</p><p>数字杠杆。</p><p>让我描绘一下我的意思。</p><p>拥有超过50万的粉丝和稳固的声誉，我可以：</p><ul><li>联系几乎任何人，甚至是名人，并得到回复。</li><li>推广一个产品、服务或信息，使其触达的人数达到我现有粉丝数的10倍。</li><li>通过战略性地投入时间或金钱，在特定范围内增加或减少我的收入。</li></ul><p>如果我必须在24小时内赚到5万美元，我有这个杠杆来做到。见鬼，如果我<em>真的</em>努力一把，我可以在24小时内赚到10万美元，并且不欠任何人的人情或金钱，但我可能不得不跨越一些道德界限。这感觉不太好。</p><p>而在一些特殊场合，比如黑色星期五周末，我这个小小的创作者企业带来了13.9万美元的收入。</p><p><img src="'+t+'" alt=""></p><p>这并不总是可行的，并且在我拥有大量粉丝之前绝对是不可行的。</p><p>JK·莫利纳（JK Molina）说过“点赞不是现金”，这没错，但光有现金也不是杠杆。</p><p>当然了，就像我谈论的任何事情一样，这取决于你的目标。</p><p>如果你想围绕自己的兴趣创造内容，不雇佣员工，并解锁充裕的时间和金钱……这就是为你准备的。</p><p>如果你的目标不同，不要让几张耀眼的截图分散了你的注意力，从而放弃开辟你自己的道路。</p><h2 id="精神垄断" tabindex="-1">精神垄断 <a class="header-anchor" href="#精神垄断" aria-label="Permalink to &quot;精神垄断&quot;">​</a></h2><blockquote><p>互联网促成了八十亿个垄断。—— 纳瓦尔（Naval）</p></blockquote><p>简单来说，你的“个人品牌”是基于你从生活中想得到什么。</p><p>这是你<em>引领</em>你的<em>粉丝</em>走向的目标。</p><p>每个人都有相同的渴望。</p><p>它们都围绕着永恒的市场：</p><ul><li>健康</li><li>财富</li><li>人际关系</li><li>附加项：幸福</li></ul><p>前三个是基于生存或自我实现的（参见：马斯洛需求层次理论）。</p><p>最后一个是基于超越的（参见：马斯洛在他去世前计划完成的需求层次的下一阶段）。</p><p>这些市场中存在着迫在眉睫的问题。那些相关的、有利可图的且永不过时的问题。每个人都有与这些市场相关的、有意识或无意识的目标。</p><p>现在，我们不想成为一个普普通通的“个人品牌”，我们想成为一个个人垄断者。</p><p><em>你作为创作者的长期成功，取决于你创造的精神垄断占据了集体意识中的一小块地盘。</em></p><p><em>不可替代</em>是个好词。</p><p>我们如何变得不可替代？</p><p>通过追求你真正的好奇心。</p><p>那正是让你成为你的原因。</p><p>如果你是这个星球上唯一的“你”，你那<em>只有你一个人的细分领域</em>就已经开辟出来了。</p><p>但是，大多数人无法追求他们的好奇心。至少无法持续地追求。</p><p>为什么？</p><p>因为他们的注意力正在被他们最基本的心理需求粗暴地操控着。</p><p>对于过上美好的生活来说，自我实现是一种需要，而不是一种想要。</p><p><em>你的未来不是与他人的竞争，而是与你那分散注意力的头脑之间的竞争。</em></p><p>意思是，非凡的未来属于那些能够掌控自己的生存、追求自己真正的好奇心，并传授所学知识的人。</p><p>所以：</p><ol><li>提升自己</li><li>解决你自己的问题</li><li>掌控你的生存</li><li>记录你的旅程</li><li>追求你的好奇心并将自己与人群区分开来</li></ol><p>你如何做到这一点对你来说是独一无二的。</p><p>如果你的目标是财务自由，你的道路将与他人不同。你的<em>故事</em>正是将你变成只有你一个人的细分领域的原因。</p><p>如果你和我都是通过不同的技能、兴趣以及在挣扎中学到的教训实现了财务自由，我们将会有截然不同的故事可讲。</p><p>这个故事对我们的下一代很有价值，并且对你的品牌成功至关重要。</p><p>为什么这很重要？</p><p>因为这就是我们在这里要做的事情。</p><p>自我实现并超越。</p><p>传授你的教训。</p><p><em>帮助别人更快地到达那里。</em></p><p>为人类做好事，并获得好的回报。</p><p>如果有足够多的人这样做，想象一下你能帮助创造一个什么样的世界。</p><p>如果更多的人解决了他们基本的生存需求，他们就为创造性地解决问题腾出了空间。</p><p><em>通过追求好奇心而产生的创造力、创新和发现，将把我们带入进化的下一个阶段，无论它可能是什么。</em></p><h2 id="分发-自由" tabindex="-1">分发 = 自由 <a class="header-anchor" href="#分发-自由" aria-label="Permalink to &quot;分发 = 自由&quot;">​</a></h2><blockquote><p>先建立分发，然后建立你想要的任何东西。—— 杰克·布彻（Jack Butcher）</p></blockquote><p>从创作者企业的视角来看，“分发”就是你可以引流到某个产品、服务或互联网任何一个角落的<em>潜在流量</em>。</p><p>分发有3种类型：</p><p><em>自建的，借用的，以及买来的。</em></p><p>你通过在互联网上用内容来增长受众，从而<strong>建立</strong>分发。然后，你可以（也应该）更进一步，将你的受众“去平台化”。</p><p>你通过将受众漏斗式地引导到社区或新闻通讯来实现去平台化。这些可以是免费的，也可以是付费的。</p><p>社交媒体平台随时可能*砰*的一声就没了。你的账号可能会被封停，你可能会遭到网暴抵制，或者你可能只是受够了社交媒体而选择离开。</p><p>但是，他们无法从你手中夺走一个脱离平台的社区或电子邮件列表。而且，这些是你最忠实的读者，所以无论如何最好把最多的价值和注意力给到他们。</p><p>你通过利用别人的受众、社区或新闻通讯来<strong>借用</strong>分发。</p><p>你可以在他们的播客中做客，并宣传你提供的产品或服务。</p><p>或者，你的想法可能如此独特，以至于即使你不在场，他们也会在播客中提及你。他们可以在他们的帖子、新闻通讯、甚至有时在一本成熟的书里认可你的观点。</p><p>这是你最终想玩的游戏。让你的想法变得如此具有感染力，以至于你的分发渠道在无需任何手动努力的情况下继续增长。</p><p>让你的想法在人们的脑海中免费安家。</p><p>你可以通过许多不同的方式<strong>购买</strong>分发。</p><p>各种付费广告的选项显而易见，但并不是最强大的。</p><p>你可以购买播客、新闻通讯和YouTube视频上的赞助位。</p><p>你也可以购买付费分享，比如转发、Instagram快拍，甚至YouTube视频上的“接下来观看”槽位。如果有人好奇，我还没试过这个，我最近在YouTube上的增长是凭空发生的（但我不反对测试一下）。</p><p>最后一个，付费增长，是我最喜欢的，因为它通常会带来大量高互动的人群来关注你。你没有告诉他们来关注你，他们关注是因为你的内容好。这会随着时间复利，并与“自建的”分发交叉融合。</p><p>对此常见的反对意见是“作弊”，这通常是那些不在创作者这个游戏里的人喋喋不休的。如果你的品牌、内容或产品很糟糕，你是不会增长、卖不出去东西，也不会被视为任何形式的权威的。</p><p>买来的流量会将你已经拥有的结果、想法以及在这个游戏中投入的时间进行复利放大。</p><p><img src="'+a+'" alt=""></p><p>那张图片就是我目前的分发网络。</p><p>我在多个平台上拥有超过50万的粉丝，4万以上的新闻通讯订阅者，以及一个让我能舒舒服服地资助我想要的生活方式的产品矩阵。</p><p>太多人忘记的一件事是：</p><p>你的受众不仅仅是<em>你的</em>受众。</p><p><em>网络效应</em>极其强大。</p><p>我不仅仅能接触到我自己的粉丝。</p><p>我间接地能接触到关注我的每个人的粉丝——这些人中有很多是微网红或拥有十万级以上受众的其他人。</p><p>我还能接触到那些通过数字形式或口口相传分享我内容的人群。</p><p>并且，我能接触到每一个关注我的人的“粉丝”。当然，程度要弱一些。</p><p>关键在于，如果（1）我保持持续产出，（2）我优先考虑那些能让人记住的创意想法，那么我的想法就有一点可能性去触达互联网上45亿人中的任何一个。</p><p>拥有50万粉丝，我间接拥有了10倍以上的潜在流量入口。对于较小的粉丝群体也是如此，只是他们没有意识到。</p><h3 id="不需要花费时间的产品" tabindex="-1">不需要花费时间的产品 <a class="header-anchor" href="#不需要花费时间的产品" aria-label="Permalink to &quot;不需要花费时间的产品&quot;">​</a></h3><p>我们将在下一节讨论你应该专注于什么形式的产品或服务，但首先让我们明白这一点：</p><p><em>你的收入、生活方式和自由，都受限于你的产品在交付上所花费的时间。</em></p><p>预计未来十年内将有62%的体力劳动岗位面临自动化的威胁，这就说得通了：收入最高的人将是那些优先销售知识的人。</p><p>当你拥有了惊人的分发量，但却只有一种需要占用你宝贵时间的服务时，那可就一点也不好玩了。</p><p>你手头没有一款能在你睡觉时进行销售、交付和自我维护的产品。如果因为别人在播客等地方提到你的想法而带来了流量涌入，你实际上就是在把钱（以及更多的杠杆）冲进下水道。</p><p><strong>另一件事：</strong></p><p>你帮助的人越多，你拥有的杠杆就越大。</p><p>如果人们深入研究了你那些深刻、有价值且可执行的想法、系统和建议——你就占据了更多的心智资产。</p><p>那些只卖高客单价教练服务、自由职业工作或咨询服务的人并没有这种力量。</p><p>就像你会用余生记住你最喜欢的书的作者一样。</p><p>书籍、数字产品和高价值长篇内容，比用自由职业或教练去服务几个特定的人，具有更高的潜在影响力。</p><p>你对世界的影响力越大——你<em>吸引</em>的注意力越多——你拥有的杠杆就越大。</p><h2 id="互联网内容是一场关于心智地产的思想战" tabindex="-1">互联网内容是一场关于心智地产的思想战 <a class="header-anchor" href="#互联网内容是一场关于心智地产的思想战" aria-label="Permalink to &quot;互联网内容是一场关于心智地产的思想战&quot;">​</a></h2><p>大多数一人企业初学者都没有看清内容的本质。</p><p>它不在于吸引注意力。</p><p>它不是为了获得最多的粉丝。</p><p>它也不是为了获得最高的互动量。</p><p>它的核心在于有价值的观点。</p><p>有价值的观点 = 相关、易懂且高度可落地，甚至能达到不需要你亲自推动就能自发传播的程度。</p><p>你向世界输出的颠覆认知的观点越多，你占据的心智地产就越多。</p><p>最大的问题在于：</p><p>从其他创作者那里窃取高分观点是一个常见（且很好）的建议。</p><p>我一直都在这么做。</p><p>我会从这些地方窃取观点：</p><p><strong>高播放量的 YouTube 视频</strong>——去一个你渴望成为的那类频道，按最受欢迎的视频进行筛选。</p><p><strong>Medium 文章</strong>——Medium 的算法会根据你的兴趣为你推送内容。仅仅略读一下主页，你就能获得一些不可思议的绝佳观点。</p><p><strong>热门推文</strong>——使用 Twemex 或 TweetHunter，你可以筛选任何账号的推文，看看他们表现最好的内容是什么。</p><p>以上是一些常见的例子。问题在于缺乏平衡、测试，以及没有通过亲身经历将这些观点转化为你自己的东西。</p><p>我在 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a> 中对此有更多探讨。</p><p>现在，让我们来了解一下你这段旅程的演变过程。</p><p>就像生活中的所有领域一样，这也有不同的发展阶段。</p><p>这些阶段都有一系列与其技能、结果和经验相匹配的机会。</p><p>一个处于第一阶段的创作者不可能像第三阶段那样，发封邮件就能随时赚到 5 万美元。他们也不可能给任何人发私信都能得到回复，不可能在私信里随意挑选商业机会，也不可能因为没有客户要服务而拥有直接消失 3 个月的自由。</p><p>你需要通过<a href="https://thedankoe.com/become-a-free-thinker-if-you-want-creative-business-success/" target="_blank" rel="noreferrer">不断突破自己的认知边界</a>来发展你自己和你的业务。</p><p><strong>前言</strong>：所有这些阶段都是我根据多年来的观察总结出来的。它们并不是一成不变的，也不适用于所有人。而且，这主要适用于那些没有过往商业成功经验的一人企业创作者。</p><h3 id="第一阶段创作者-低杠杆" tabindex="-1">第一阶段创作者（低杠杆） <a class="header-anchor" href="#第一阶段创作者-低杠杆" aria-label="Permalink to &quot;第一阶段创作者（低杠杆）&quot;">​</a></h3><p>这是每一个新创作者的起点。</p><p>社交媒体的增长是公式化的。这些阶段将帮助你更好地理解它。</p><p>大多数人认为自己无法积累受众，但当他们看着自己最喜欢的创作者的内容时，明明知道自己也具备同样的知识，却没有意识到社交媒体是一项可以通过练习和坚持来学习的<em>技能</em>，就像其他任何技能一样。</p><p>以下是你在创作者旅程的第一阶段需要关注的内容：</p><p><strong>1) 高表现内容</strong></p><p>你需要了解究竟什么样的内容才能真正带来增长。</p><p>你不能随心所欲地发布你想发的内容，然后仅仅因为你自认聪明又带点艺术气质，就指望它能火。</p><p>如果你没有实现增长，这绝不是读者看不懂你文章的错，而是你的错，因为你没能用易于理解的方式去写作。</p><p>研究热门推文、爆款内容和引人注目的标题。让自己沉浸其中，解构它们为何有效，并开始在自己的内容中测试你学到的东西。</p><p><strong>2) 将内容模板作为辅助轮</strong></p><p>几乎每一个社交媒体课程都有你可以套用的内容模板。把它们当作你的辅助轮。</p><p>这是我每天都会重复使用的一个模板。现在，把我的写作结构化为易于消化、易于分享和易于理解的形式，对我来说已经是第二天性了：</p><blockquote><p>相信我的话：\\</p><p>– 写下你的目标<br> – 将它们细化为小任务<br> – 每天为每个任务排好优先级\\</p><p>这会让实际实现你的目标变得容易 100 倍\\</p><p>依赖你的记忆并不可靠，周围全是干扰</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1266299534893711360?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">May 29, 2020</a></p></blockquote><p>当你在研究高表现内容时，要密切关注它的结构。</p><p>钩子 &gt; 价值 &gt; 结论。</p><p>练习将你的观点套入这些结构中。</p><p><strong>3) 短内容增长与观点验证</strong></p><p>推文、Reels、TikTok 视频、Shorts 短视频、Instagram 帖子以及 LinkedIn 帖子，全都是短内容的类型。</p><p>在初期，社交媒体平台应被视为“漏斗顶部”的增长机制。你当然可以随时开始测试权威性和真实性风格的内容，但你必须先实现增长。</p><p>如果你能精通短内容，当你准备进化到第二和第三阶段时，你将拥有一个坚实的基础。</p><p><strong>如果你被困在这个阶段会发生什么？</strong></p><p>你最终会成为一个粉丝量很高但毫无忠诚度的品牌。</p><p>如果有一天你消失了，没有人会问自己：“嘿，Dan 去哪儿了？”</p><p>这类人对互动量的痴迷以及总在提供最基础的建议，会导致账号的变现潜力极低。</p><p>想要全面掌控自己的收入、生活方式和所把握的机会，对他们来说更是天方夜谭。</p><p>他们出于稀缺心态行事，因为他们还没有通过自我发展掌握真正的生存之道。</p><h3 id="第二阶段创作者-中等杠杆" tabindex="-1"><strong>第二阶段创作者（中等杠杆）</strong> <a class="header-anchor" href="#第二阶段创作者-中等杠杆" aria-label="Permalink to &quot;**第二阶段创作者（中等杠杆）**&quot;">​</a></h3><p>一旦你达到 1 万左右的粉丝，你应该会觉得你已经完全拿下了社交媒体增长的这场游戏。</p><p>你不必等到这个时候才开始变现，而且<a href="https://thedankoe.com/the-one-person-business-model-how-to-monetize-yourself/" target="_blank" rel="noreferrer">我其实建议不要等</a>，但真正赚大钱的阶段是从这里开始的。</p><blockquote><p>在 500 个粉丝时，我月入 3,000 美元\\</p><p>在 10,000 个粉丝时，我月入 10,000 美元\\</p><p>在 50,000 个粉丝时，我月入 50,000 美元\\</p><p>在 200,000 个粉丝时，我月入 150,000 美元\\</p><p>如果这让你感到震惊，很好。\\</p><p>如果没有，厉害。\\</p><p>希望这能打破一些人对金钱的限制性信念。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1596895970519924738?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">November 27, 2022</a></p></blockquote><p>如果你没能实现每个粉丝为你带来 1 美元，你可以提升自己的技能来达到这个基准线。</p><p><strong>1) 学习直效营销 (Direct Response)</strong></p><p>直效营销或直效文案的目的，是说服人们立即完成转化。销售和报价单（offer）的创建也归入其中——非常值得深入研究。</p><p>正是这项技能，让像 Alex Hormozi 这样的人在毫无保留地免费公开一切、全力投入个人品牌建设之前就已经赚得盆满钵满。你也应该免费公开所有东西，但要通过长内容在数年的时间里循序渐进地给出。把那些可落地的要点<a href="https://thedankoe.com/you-have-100000-of-knowledge-trapped-in-your-brain/" target="_blank" rel="noreferrer">以系统的形式汇编成一个付费产品</a>。</p><p>像 Justin Welsh 和社交媒体领域中的许多其他人也是同样的故事。他们以服务型业务起家，啃透了 Whitman 的《Ca$hvertising》等直效营销经典，哪怕后来他们转向更“真实”的个人声音——这些广告学原理依然构成了他们营销和内容的基石。</p><p>通过学习直效营销，你能更深刻地理解买家心理，并会看到你的报价、转化率和基础收入出现大幅提升。</p><p><strong>2) 打造高客单价报价 (High Ticket Offer)</strong></p><p>当你的粉丝数量在 1 万到 8 万之间时，你在这个游戏中沉淀的时间还不足以让你在没有高客单价产品的情况下赚取大笔财富。</p><p>（我是站在没有任何商业经验却开始创作者创业的背景下说这番话的）。</p><p>这就需要围绕你的兴趣和技能，引入自由职业、咨询或辅导业务了。我在这里谈到了如何创建一个<a href="https://thedankoe.com/the-one-person-business-model-how-to-monetize-yourself/" target="_blank" rel="noreferrer">最小可行性报价并进行迭代</a>。</p><p>在这个阶段，你拥有充足的流量——希望能同时拥有充足的技能——以每月 2500 到 5000 美元的价格拿下 4 个以上的客户。</p><p>所有这些数字都是<em>估算值</em>，取决于由真实世界经验支撑的你的真实技能水平，而不是你自认为的技能水平。</p><p>专注于取得成果，完善你独特的系统，并为迈向第三阶段做好准备。</p><p>顺便说一句，我在 Modern Mastery 社区里，为我们这里讨论的每一件事都提供了策略和路线图。<a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">读者可以花 5 美元加入。</a></p><p><strong>3) 拓展到长内容领域</strong></p><p>到现在，你已经获得了足够的成长，清楚哪些推文、帖子或观点表现得好。</p><p>你需要开始剖析这些观点，并为它们构建深度。</p><p>你可以通过将已经验证过的观点转化为长篇播客、newsletter（订阅通讯）或 YouTube 视频来实现这一点。</p><p>你在这些观点背后赋予的深度，将把普通粉丝转化为死忠粉。而且，你将找到处理这些观点的新方法，从而开始建立你的心智垄断。</p><p>我建议从写 newsletter 开始。</p><p>长篇内容不会消失。你可以积累 20 多篇 newsletter，以后再将它们重新排版复用到其他平台上。</p><p><strong>如果你被困在这个阶段会发生什么？</strong></p><p>你会给自己硬生生造出另一份朝九晚五的工作。</p><p>你掌握了生存的本领，但却没有顺应你的好奇心去发展。</p><p>你拥有刚好够维持生计的客户，却没有足够的时间去利用你辛苦建立起来的杠杆。</p><h3 id="第三阶段创作者-高杠杆" tabindex="-1"><strong>第三阶段创作者（高杠杆）</strong> <a class="header-anchor" href="#第三阶段创作者-高杠杆" aria-label="Permalink to &quot;**第三阶段创作者（高杠杆）**&quot;">​</a></h3><p>许多人永远都达不到这个阶段。</p><p>为什么？</p><p>因为如果没有生存能力的掌握、心智的发展以及跨学科的学习，这根本不可能实现。</p><p>人们很容易陷入“只做一件事”的思维定势中（这在初期并不是坏事），把自己困在高客单价客户的死循环里，不再去追求补充性的兴趣和技能。</p><p><strong>1) 产品化、建立人脉网络并利用成果作为杠杆</strong></p><p>到现在，你可能已经创建了一款产品。如果是的话，干得漂亮。</p><p>但是，到现在，你也绝对应该从你的服务中拿到了实质性的成果。</p><p>你已经迭代了用来获取成果的系统，取得了更好的成绩，现在可以在各处利用这些成果作为你的杠杆了。</p><p>我的建议是：</p><ul><li>提取你获取成果的系统和方法</li><li>将其重新定位，面向更广泛的受众（初级水平）</li><li>利用你的成果作为初始的社会认同（Social Proof），实现六位数的发售</li></ul><p>如果你想了解更多关于将知识产品化的内容，<a href="https://thedankoe.com/you-have-100000-of-knowledge-trapped-in-your-brain/" target="_blank" rel="noreferrer">我在这里写过相关的文章</a>。</p><p>通过高粉丝数和绝佳观点所积累的社会认同，能为你敲开与其他行业大玩家合作的大门。</p><p>给他们发私信。主动提供你力所能及的帮助。最终，你将拥有 5 到 10 个值得信赖的盟友，共同寻求跨平台增长和各种商业机会。</p><p><strong>2) 提炼观点并实现多元化</strong></p><p>上面展示我分发网络图表包含了 3 个关键领域：增长（Growth）、真实性（Authenticity）和权威性（Authority）。</p><p><img src="'+o+'" alt=""></p><p>增长来源于短内容。</p><p>权威性来源于产品或服务取得的成果。</p><p>真实性来源于长篇内容对宏大观点的整合。</p><p>当然，它们相互之间都有重叠。权威性和真实性同样可以应用于短内容等等。</p><p>在第一阶段，你 80% 以上的内容应侧重于增长。</p><p>在第二阶段，你开始围绕你销售的产品或服务融入更多的权威性内容。你也开始通过长内容涉足真实性领域。</p><p>在第三阶段，是时候对你最棒的观点加倍下注，并利用它们在其他平台上实现爆发增长了。</p><p>我在 Instagram 和 LinkedIn 上增长得非常快，方法是：</p><ul><li>联系这些平台上的大号</li><li>向他们展示我的价值（我的粉丝量）和在这个领域的资历</li><li>提供服务交换、转发互推或金钱，以最优的方式帮助我实现增长</li></ul><p>我拥有表现已经很好的内容。</p><p>所以，当我带着稳固的增长策略进入一个新平台时……我需要做的就是利用我过去的内容，把它展示在我的人脉网络的人脉面前，从而快速增长。</p><p><strong>3)</strong> <strong>优先考虑长内容</strong></p><p>一旦你的收入和粉丝量达到一定高度，就该把重点放在成为一个知识综合者上了。</p><p>当然，你可以在一开始就这么做，但这才是它对你品牌未来变得至关重要的阶段。</p><p>这最好通过长内容来实现。</p><p>简而言之，你要：</p><ol><li>追求你感兴趣的事物</li><li>研究<em>这些兴趣的大局观念</em></li><li>根据你的经验注意其中的模式</li><li>用长内容将这些点连接起来</li><li>创造你自己版本的概念、流程和哲学</li><li>提取长内容中的片段用于你的短内容</li></ol><p>这就是商业变得极其令人满足的地方。</p><p>我就是这样创造出自己的“一人企业”概念的，它为所有这些东西提供了一种新颖的方法。其他人也经常谈论一人企业，但他们是通过同样的、被淡化的视角来看待，那并不怎么有趣。</p><p>我还为一些流程命名，比如智能模仿（Intelligent Imitation）、未知域（The Unknown）和战术压力（Tactical Stress）。</p><p>这是源于将我的任何兴趣——比如哲学、神经生物学和灵性——应用到商业中。我对所有这些领域都有足够的接触，所以我能注意到共同的模式。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><blockquote><p>方法可能有成千上万种，但原则却屈指可数。掌握了原则的人，能够成功地选择出适合自己的方法。——哈灵顿·埃默森（Harrington Emerson）</p></blockquote><p>这整封信就是<em>我的</em>基于原则的方法。</p><p>不要把它当作铁律。</p><p>显然，这并不是做生意的唯一方式。</p><p>去尝试，去实验，创造出你自己的做事方式。</p><p>这封信的主要教训应该是我一直在倡导的：</p><p>永远不要停止学习。</p><p>永远不要停止建设。</p><p>永远不要停止进化。</p><p>分心和安逸是唯一能阻碍你的东西。</p><p>自我实现 &gt; 自我变现 &gt; 自我超越。</p><p>——丹·柯（Dan Koe）</p><p><strong>本周动态</strong></p><p>数字经济学（Digital Economics）现已向公众开放。你可以随时报名。<em>而且，你可以免费访问 Digital Economics 101（一门迷你课程）</em>。如果你对用我通过 3 年创作者经验打磨出的<em>系统</em>将自己产品化感兴趣，请考虑报名参加完整版课程。</p><p><a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">查看数字经济学（Digital Economics）。</a></p><p>在 YouTube 上，我发布了一个关于我是如何记住我学到的所有东西的视频。这是快速学习新技能并获得现实成果的最佳方式。本周，我将发布一个关于如何把你脑子里的知识变成可盈利产品的视频。</p><p><a href="https://youtube.com/c/DanKoeTalks" target="_blank" rel="noreferrer">在这里订阅并观看。</a></p><p>在《现代精通》（Modern Mastery）中，我发布了一份关于“如何将多种兴趣‘细分领域化’”的培训。</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">读者只需 5 美元即可加入。</a></p><p>如果你想查看我的免费工具、顶级评价的产品或以前的信件——<a href="https://thedankoe.com/" target="_blank" rel="noreferrer">访问我的网站</a>。</p><hr><p><a href="/en/letters/the-one-person-business-roadmap-99-of-creators-make-this-mistake">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',256))])}const y=s(u,[["render",g]]);export{T as __pageData,y as default};
